// ---- RF-007: ventas por canal (docs/cambios/2026-11-11-ventas-por-canal.md) ----
const ventaCanal = (id, sku, cantidad, precio, canal) =>
  crearVentaRegistrada({ id, fecha: "2026-11-02", sku, cantidad, precioUnitarioCentavos: precio, canal });
const CERO = { unidades: 0, totalCentavos: 0 };
const CON_CANAL = [
  ventaCanal("V-1", "CAFE-250", 2, 4500),
  ventaCanal("V-2", "TE-100", 5, 1200, "web"),
  ventaCanal("V-3", "CAFE-250", 1, 4500, "tienda"),
  ventaCanal("V-4", "TE-100", 3, 1000, "web"),
];
const AJUSTE = crearStockAjustado({ id: "S-9", fecha: "2026-11-01", sku: "CAFE-250", delta: 4, motivo: "compra", almacen: "ALM-02" });

test("T-01 RF-007: ventas en los dos canales, con y sin canal", () => {
  assert.deepEqual(ventasPorCanal(CON_CANAL), {
    tienda: { unidades: 3, totalCentavos: 13500 },
    web: { unidades: 8, totalCentavos: 9000 },
  });
});

test("T-02 RF-007: una venta sin canal cuenta como tienda", () => {
  assert.deepEqual(ventasPorCanal([ventaCanal("V-1", "CAFE-250", 2, 4500)]), { tienda: { unidades: 2, totalCentavos: 9000 }, web: CERO });
});

test("T-03 RF-007: solo ventas web deja tienda en ceros", () => {
  assert.deepEqual(ventasPorCanal([ventaCanal("V-1", "TE-100", 1, 1200, "web")]), { tienda: CERO, web: { unidades: 1, totalCentavos: 1200 } });
});

test("T-04 RF-007: lista vacía y precio cero", () => {
  assert.deepEqual(ventasPorCanal([]), { tienda: CERO, web: CERO });
  assert.deepEqual(ventasPorCanal([ventaCanal("V-1", "TE-100", 4, 0, "web")]), { tienda: CERO, web: { unidades: 4, totalCentavos: 0 } });
});

test("T-05 RF-007: ignora los stock.ajustado, con y sin almacén", () => {
  const sinAlmacen = crearStockAjustado({ id: "S-8", fecha: "2026-11-01", sku: "TE-100", delta: 1, motivo: "compra" });
  assert.deepEqual(ventasPorCanal([...CON_CANAL, AJUSTE, sinAlmacen]), ventasPorCanal(CON_CANAL));
});

test("T-06 RF-007: valida con el contrato y rechaza lo que no lo cumple", () => {
  const base = { tipo: "venta.registrada", id: "V-1", fecha: "2026-11-02", sku: "CAFE-250", cantidad: 1, precioUnitarioCentavos: 100 };
  for (const canal of ["telefono", "Web", "", null]) assert.throws(() => ventasPorCanal([{ ...base, canal }]), RangeError);
  assert.throws(() => ventasPorCanal([{ ...base, extra: 1 }]), TypeError);
  const { cantidad, ...sinCantidad } = base;
  assert.throws(() => ventasPorCanal([sinCantidad]), TypeError);
  assert.throws(() => ventasPorCanal([...CON_CANAL, { tipo: "stock.ajustado", id: "S-1", fecha: "2026-11-01", sku: "TE-100", delta: 1 }]), TypeError);
  assert.throws(() => ventasPorCanal([{ tipo: "otra.cosa" }]), TypeError);
});

test("T-07 RF-004: resumenVentas y topProductos no cambian con eventos con canal", () => {
  assert.deepEqual(resumenVentas(CON_CANAL), { ventas: 4, unidades: 11, totalCentavos: 22500 });
  assert.deepEqual(topProductos(CON_CANAL, 2), [{ sku: "TE-100", unidades: 8 }, { sku: "CAFE-250", unidades: 3 }]);
});
'@
